using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text;
using System.Text.Json;

namespace NomadNet.Tests;

// Generated by executing primary Browser.should_load_images and last_response_speed at
// f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2; generator/fixture record the actual file SHA-256.
[Trait("Category", "Unit")]
public sealed class NomadNetInlineMediaTests
{
    [Fact]
    public void AutomaticPolicyUsesActualPrimaryStrictRttAndBitRateBoundaries()
    {
        using var fixture = JsonDocument.Parse(typeof(NomadNetInlineMediaTests).Assembly
            .GetManifestResourceStream("NomadNet.Tests.NomadNetInlineMediaVectors.json")!);
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", fixture.RootElement.GetProperty("commit").GetString());
        foreach (var item in fixture.RootElement.GetProperty("vectors").EnumerateArray())
        {
            double? Number(string name) => item.GetProperty(name).ValueKind == JsonValueKind.Null ? null : item.GetProperty(name).GetDouble();
            var mode = NomadNetImagePolicy.Parse(item.GetProperty("mode").GetString()!);
            Assert.Equal(item.GetProperty("value").GetInt32(), (int)mode);
            var metrics = new NomadNetImageLinkMetrics(Number("rtt"), Number("expectedRate"),
                (long?)Number("transferBytes"), Number("responseSeconds"));
            Assert.Equal(Number("fallbackRate"), metrics.ResponseBitsPerSecond);
            Assert.Equal(item.GetProperty("load").GetBoolean(), NomadNetImagePolicy.ShouldLoad(mode,
                item.GetProperty("local").GetBoolean(), item.GetProperty("linked").GetBoolean() ? metrics : null));
        }
    }

    [Fact]
    public void InvalidModesAndNonfiniteMetricsAreNotNetworkAdmission()
    {
        Assert.Throws<InvalidDataException>(() => NomadNetImagePolicy.Parse("yes"));
        Assert.Throws<ArgumentOutOfRangeException>(() => NomadNetImagePolicy.ShouldLoad((NomadNetImageLoading)99, true, null));
        foreach (var value in new[] { double.NaN, double.PositiveInfinity, double.NegativeInfinity, -1 })
        {
            Assert.False(NomadNetImagePolicy.ShouldLoad(NomadNetImageLoading.Auto, false, new(value, 20000, null, null)));
            Assert.False(NomadNetImagePolicy.ShouldLoad(NomadNetImageLoading.Auto, false, new(0.1, value, null, null)));
        }
        Assert.Equal(NomadNetImageLoading.Auto, new NomadNetSettings().ImageLoading);
        Assert.Equal(NomadNetImageLoading.Always, NomadNetImagePolicy.Parse("ALWAYS"));
    }

    [Fact]
    public async Task ManualAndAutomaticLoadingContinueAfterFailuresWithoutObserversAndRetryOnlyExplicitly()
    {
        var good = new NomadNetPageMedia("good", "/media/good.webp");
        var bad = new NomadNetPageMedia("bad", "/media/bad.webp");
        var page = new NomadNetRenderedPage("page", []) { Media = [bad, good, good] };
        var attempts = new Dictionary<NomadNetPageMedia, int>();
        await using var images = new NomadNetInlineMedia((image, reload, _) =>
        {
            attempts[image] = attempts.GetValueOrDefault(image) + 1;
            if (image == bad && !reload) throw new IOException("bad image");
            return Task.FromResult("PREVIEW");
        }) { Log = _ => throw new InvalidOperationException("bad logger") };
        images.Start();
        images.Show(page, false);
        Assert.Empty(attempts);
        await images.LoadAsync();
        Assert.Equal(1, attempts[bad]);
        Assert.Equal(1, attempts[good]);
        await images.LoadAsync();
        Assert.Equal(1, attempts[bad]);
        images.Changed += _ => throw new InvalidOperationException("bad observer");
        var observed = 0;
        images.Changed += _ => observed++;
        await images.LoadAsync(reload: true);
        Assert.Equal(2, attempts[bad]);
        Assert.Equal(2, attempts[good]);
        Assert.Equal(2, observed);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task MissingAndThrowingLogObserversReportContextThroughTraceWithoutStoppingImages(bool throwingLog)
    {
        using var listener = new CapturingTraceListener();
        Trace.Listeners.Add(listener);
        try
        {
            var page = MicronText.Render("`(bad`/media/trace-bad.webp)\n`(good`/media/trace-good.webp)"u8);
            var bad = page.Media[0];
            await using var images = new NomadNetInlineMedia((image, _, _) =>
                image == bad ? throw new IOException("trace-preview-failed") : Task.FromResult("TRACE_PREVIEW"));
            if (throwingLog) images.Log = _ => throw new InvalidOperationException("trace-log-callback-failed");
            images.Changed += _ => throw new InvalidOperationException("trace-image-observer-failed");
            var observed = 0;
            images.Changed += _ => observed++;
            images.Start();
            images.Show(page, false);
            await images.LoadAsync();
            Assert.Equal(2, observed);
            Assert.Contains("TRACE_PREVIEW", images.Render(page));
            var reports = string.Join('\n', listener.Messages);
            Assert.Contains("NomadNet inline image", reports);
            Assert.Contains("/media/trace-bad.webp: trace-preview-failed", reports);
            Assert.Contains("Inline image observer failed: trace-image-observer-failed", reports);
            if (throwingLog)
            {
                Assert.Contains("log observer failed: trace-log-callback-failed", reports);
                Assert.Contains("original report:", reports);
            }
        }
        finally { Trace.Listeners.Remove(listener); }
    }

    [Fact]
    public async Task NewPartialMediaIsLoadedButOldResultsNeverAppearInAnotherPage()
    {
        var first = Page("first");
        var second = Page("second");
        var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var release = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var completed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        await using var images = new NomadNetInlineMedia(async (image, _, token) =>
        {
            if (image.Alt == "first") { entered.TrySetResult(); await release.Task.WaitAsync(token); }
            return "PREVIEW_" + image.Alt;
        });
        images.Start();
        images.Changed += page => { if (images.Render(page).Contains("PREVIEW_second", StringComparison.Ordinal)) completed.TrySetResult(); };
        images.Show(first, true);
        await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));
        images.Show(second, true);
        release.SetResult();
        await completed.Task.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.Contains("PREVIEW_second", images.Render(second));
        Assert.DoesNotContain("PREVIEW_first", images.Render(second));
    }

    [Fact]
    public async Task RepeatedDisposalJoinsInFlightCleanupAndCancelsQueuedManualWork()
    {
        var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var canceled = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var cleanup = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var images = new NomadNetInlineMedia(async (_, _, token) =>
        {
            entered.TrySetResult();
            try { await Task.Delay(Timeout.InfiniteTimeSpan, token); }
            finally { canceled.TrySetResult(); await cleanup.Task; }
            return "";
        });
        images.Start();
        images.Show(Page("cancel"), false);
        var pending = Enumerable.Range(0, 16).Select(_ => images.LoadAsync()).ToArray();
        await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.Throws<InvalidOperationException>(() => { _ = images.LoadAsync(); });
        var first = images.DisposeAsync().AsTask();
        var second = images.DisposeAsync().AsTask();
        await canceled.Task.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.False(first.IsCompleted);
        Assert.False(second.IsCompleted);
        cleanup.SetResult();
        await Task.WhenAll(first, second).WaitAsync(TimeSpan.FromSeconds(5));
        foreach (var task in pending) await Assert.ThrowsAnyAsync<OperationCanceledException>(() => task);
        Assert.Throws<ObjectDisposedException>(() => images.Show(Page("late"), true));
        Assert.Throws<ObjectDisposedException>(() => images.Start());
    }

    [Fact]
    public async Task UnsafePreviewIsNeverPublishedAndDistinctImagesAreBounded()
    {
        var page = MicronText.Render(Encoding.UTF8.GetBytes(string.Join('\n',
            Enumerable.Range(0, 40).Select(index => $"`(image{index}`/media/{index}.webp)"))));
        var count = 0;
        await using var images = new NomadNetInlineMedia((_, _, _) =>
        {
            count++;
            return Task.FromResult("\x1b[2JUNSAFE");
        });
        images.Start();
        images.Show(page, false);
        await images.LoadAsync();
        Assert.Equal(NomadNetInlineMedia.MaximumImages, count);
        Assert.DoesNotContain("UNSAFE", images.Render(page));
    }

    [Fact]
    public void InlineRenderingPreservesFoldVisibilityAndFormIndices()
    {
        var page = MicronText.Render("`->Fold\n`(first`/media/first.webp)\n>Next\n`<name`value>\n"u8);
        var previews = new Dictionary<NomadNetPageMedia, string> { [page.Media[0]] = "PREVIEW" };
        Assert.DoesNotContain("PREVIEW", page.DisplayWithImages(previews));
        page.ToggleFold(1);
        Assert.Contains("PREVIEW", page.DisplayWithImages(previews));
        Assert.Contains("[image 1:", page.DisplayWithImages(previews));
        Assert.Equal(page.DisplayText, page.DisplayWithImages(new Dictionary<NomadNetPageMedia, string>()));
    }

    private static NomadNetRenderedPage Page(string name) =>
        MicronText.Render(Encoding.UTF8.GetBytes($"`({name}`/media/{name}.webp)"));

    private sealed class CapturingTraceListener : TraceListener
    {
        public ConcurrentQueue<string> Messages { get; } = new();
        public override bool IsThreadSafe => true;
        public override void Write(string? message)
        {
            if (message is not null) Messages.Enqueue(message);
        }
        public override void WriteLine(string? message) => Write(message);
    }
}

[Trait("Category", "Integration")]
public sealed class NomadNetRemoteMediaCacheTests
{
    [NomadNetFunctionalTests.LinuxFact]
    public async Task LinkedStorageIsRejectedBeforeCreatingAnythingOutsideTheProfile()
    {
        var root = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomadnet-image-link-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(root);
        try
        {
            var profile = Directory.CreateDirectory(Path.Combine(root, "profile")).FullName;
            var outside = Directory.CreateDirectory(Path.Combine(root, "outside")).FullName;
            var link = Path.Combine(profile, "storage");
            Directory.CreateSymbolicLink(link, outside);
            using var cache = new NomadNetRemoteMediaCache(profile);
            var fetched = false;
            await Assert.ThrowsAsync<InvalidDataException>(() => cache.GetAsync("remote:/media/test", _ =>
            {
                fetched = true;
                return Task.FromResult(Array.Empty<byte>());
            }));
            Assert.False(fetched);
            Assert.Empty(Directory.EnumerateFileSystemEntries(outside));
            Directory.Delete(link);
        }
        finally { Directory.Delete(root, true); }
    }

    [Fact]
    public async Task RuntimeImageModeUpdatesTheAuthoritativeSettingsAndSurvivesRestart()
    {
        var root = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomadnet-image-mode-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(root);
        try
        {
            await using var coordinator = new NomadNetPropagation(root, new NomadNetSettings(), () => [], _ => { },
                (_, _) => Task.FromResult(0), () => { });
            await coordinator.UpdateSettingsAsync(settings => settings with { ImageLoading = NomadNetImageLoading.Never });
            Assert.Equal(NomadNetImageLoading.Never, coordinator.Settings.ImageLoading);
            Assert.Equal(NomadNetImageLoading.Never, (await NomadNetSettings.OpenAsync(root)).ImageLoading);
            using var canceled = new CancellationTokenSource();
            canceled.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => coordinator.UpdateSettingsAsync(
                settings => settings with { ImageLoading = NomadNetImageLoading.Always }, canceled.Token));
            Assert.Equal(NomadNetImageLoading.Never, coordinator.Settings.ImageLoading);
        }
        finally { Directory.Delete(root, true); }
    }

    [Fact]
    public async Task CacheSurvivesRestartRegeneratesCorruptionAndEnforcesItsQuota()
    {
        var root = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomadnet-remote-cache-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(root);
        try
        {
            using var fixture = JsonDocument.Parse(typeof(NomadNetRemoteMediaCacheTests).Assembly
                .GetManifestResourceStream("NomadNet.Tests.NomadNetImageVectors.json")!);
            var bytes = Convert.FromBase64String(fixture.RootElement.GetProperty("vectors")[0].GetProperty("referenceWebp").GetString()!);
            var calls = 0;
            Task<byte[]> Fetch(CancellationToken _) { calls++; return Task.FromResult(bytes); }
            using (var cache = new NomadNetRemoteMediaCache(root))
            {
                Assert.Equal(bytes, await cache.GetAsync("remote:/media/test", Fetch));
                Assert.Equal(bytes, await cache.GetAsync("remote:/media/test", Fetch));
                Assert.Equal(1, calls);
            }
            using var restored = new NomadNetRemoteMediaCache(root);
            Assert.Equal(bytes, await restored.GetAsync("remote:/media/test", Fetch));
            Assert.Equal(1, calls);
            var directory = Path.Combine(root, "storage", "cache", "remote-images");
            var file = Assert.Single(Directory.EnumerateFiles(directory));
            await File.WriteAllTextAsync(file, "corruption");
            Assert.Equal(bytes, await restored.GetAsync("remote:/media/test", Fetch));
            Assert.Equal(2, calls);
            await restored.GetAsync("remote:/media/test", Fetch, reload: true);
            Assert.Equal(3, calls);
            await Assert.ThrowsAsync<InvalidDataException>(() => restored.GetAsync("bad", _ => Task.FromResult("invalid"u8.ToArray())));
            using var canceled = new CancellationTokenSource();
            canceled.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => restored.GetAsync("cancel", Fetch, cancellationToken: canceled.Token));
            for (var index = 0; index < 256; index++)
            {
                var existing = Path.Combine(directory, index.ToString("x64") + ".webp");
                await File.WriteAllBytesAsync(existing, bytes);
                File.SetLastWriteTimeUtc(existing, DateTime.UtcNow.AddDays(-1));
            }
            await restored.GetAsync("remote:/media/new", Fetch);
            Assert.Equal(NomadNetRemoteMediaCache.MaximumFiles, Directory.EnumerateFiles(directory, "*.webp").Count());
            Assert.Empty(Directory.EnumerateFiles(directory, "*.new"));
        }
        finally { Directory.Delete(root, true); }
    }
}
